import { type Content, Editor, type EditorOptions, type Extensions } from '@tiptap/core';
import Highlight from '@tiptap/extension-highlight';
import { TaskItem, TaskList } from '@tiptap/extension-list';
import Subscript from '@tiptap/extension-subscript';
import Superscript from '@tiptap/extension-superscript';
import TextAlign from '@tiptap/extension-text-align';
import { Color, FontSize, TextStyle } from '@tiptap/extension-text-style';
import Typography from '@tiptap/extension-typography';
import { CharacterCount, Placeholder } from '@tiptap/extensions';
import StarterKit from '@tiptap/starter-kit';
import AutoJoiner from 'tiptap-extension-auto-joiner';
import { ColorHighlighter } from './extensions/ColorHighlighter.js';
import SearchAndReplace from './extensions/FindAndReplace.js';
import { Table, TableCell, TableHeader, TableRow } from './extensions/table/index.js';
import 'katex/dist/katex.min.css';
import { Markdown } from '@tiptap/markdown';
import { InlineMathReplacer } from './extensions/InlineMathReplacer.js';
import strings from './strings.js';

export default (
	element?: HTMLElement,
	content?: Content,
	extensions?: Extensions,
	options?: Partial<EditorOptions>
) => {
	const editor = new Editor({
		element,
		content,
		extensions: [
			StarterKit.configure({
				orderedList: {
					HTMLAttributes: {
						class: 'list-decimal'
					}
				},
				bulletList: {
					HTMLAttributes: {
						class: 'list-disc'
					}
				},
				heading: {
					levels: [1, 2, 3, 4]
				},
				link: {
					openOnClick: false,
					autolink: true,
					linkOnPaste: true,
					HTMLAttributes: {
						target: '_tab',
						rel: 'noopener noreferrer nofollow'
					}
				},
				codeBlock: false
			}),
			CharacterCount,
			Highlight.configure({
				multicolor: true
			}),
			Placeholder.configure({
				emptyEditorClass: 'is-empty',
				// Use a placeholder:
				// Use different placeholders depending on the node type:
				placeholder: ({ node }) => {
					if (node.type.name === 'heading') {
						return strings.editor.headingPlaceholder;
					}
					if (node.type.name === 'paragraph') {
						return strings.editor.paragraphPlaceholder;
					}
					return '';
				}
			}),
			Color,
			Subscript,
			Superscript,
			Typography,
			ColorHighlighter,
			TextStyle,
			FontSize,
			TextAlign.configure({
				types: ['heading', 'paragraph']
			}),
			TaskList,
			TaskItem.configure({
				nested: true
			}),
			SearchAndReplace,
			AutoJoiner,
			Table,
			TableHeader,
			TableRow,
			TableCell,
			InlineMathReplacer,
			Markdown,

			...(extensions ?? [])
		],
		...options
	});

	return editor;
};

/* Base TipTap Editor Styles with Light/Dark Theme Support */
.edra-editor .tiptap.ProseMirror {
	margin-inline: auto;
}

.tiptap :first-child {
	margin-top: 0;
}

.tiptap :last-child {
	margin-bottom: 0;
}

.tiptap > p {
	margin: 0.5rem 0;
}

/* For Placeholder */
.tiptap .is-empty:not(blockquote.is-empty)::before {
	float: left;
	height: 0;
	color: var(--muted-foreground);
	pointer-events: none;
	content: attr(data-placeholder);
}

/* Heading Styles */
.tiptap h1,
.tiptap h2,
.tiptap h3,
.tiptap h4,
.tiptap h5,
.tiptap h6 {
	margin-top: 1rem;
	line-height: 1.2;
	text-wrap: pretty;
}

.tiptap h1,
.tiptap h2 {
	margin-top: 1rem;
	margin-bottom: 1rem;
}

.tiptap h1 {
	font-size: 2.25rem;
	font-weight: 800;
	line-height: 2.5rem;
	letter-spacing: -0.015em;
	scroll-margin: 5rem;
}

.tiptap h2 {
	font-size: 1.5rem;
	font-weight: 700;
}

.tiptap h3 {
	font-size: 1.25rem;
	font-weight: 600;
}

.tiptap h4,
.tiptap h5,
.tiptap h6 {
	font-size: 1rem;
	font-weight: 600;
}

.tiptap em {
	font-weight: 200;
}

.tiptap blockquote {
	position: relative;
	padding: 0.5rem 0;
	padding-left: 0.75rem;
	margin: 1rem 0rem;
	font-style: italic;
	color: var(--blockquote-color);
}

.tiptap blockquote::before {
	position: absolute;
	top: 0;
	bottom: 0;
	left: 0;
	width: 0.4rem;
	content: ' ';
	background-color: var(--blockquote-border);
	border-radius: 0.5rem;
}

.tiptap blockquote p {
	margin: 0;
}

/* Horizontal Rule */
.tiptap hr {
	margin: 1.5rem 0;
	border: none;
	border-top: 1px solid var(--border-color);
}

.tiptap code {
	font-family: 'Fira Code Variable', monospace;
}

/* Inline Code */
.tiptap code:not(pre code) {
	padding: 0.2rem 0.3rem;
	font-size: 0.9rem;
	font-weight: 500;
	color: var(--color-primary);
	background-color: var(--code-bg);
	border-radius: 0.25rem;
}

/* List Styling */

.tiptap ul,
.tiptap ol {
	padding: 0 1rem;
	margin: 0.5rem;
}

.tiptap ul li,
.tiptap ol li {
	margin: 0.5rem 0;
}

.tiptap ul li::marker,
.tiptap ol li::marker {
	color: var(--muted-foreground);
}

.tiptap ul li p,
.tiptap ol li p {
	margin-top: 0.25rem;
	margin-bottom: 0.25rem;
}

/* Task List Styling */
.tiptap ul[data-type='taskList'] {
	padding: 0;
	margin: 0;
	list-style: none;
}

.tiptap ul[data-type='taskList'] li {
	display: flex;
	align-items: start;
	margin: 0.5rem 0 !important;
}

.tiptap ul[data-type='taskList'] li > label {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 100%;
	margin-right: 0.5rem;
	user-select: none;
}

.tiptap ul[data-type='taskList'] li > div > p {
	margin: 0;
}

.tiptap ul[data-type='taskList'] input[type='checkbox'] {
	cursor: pointer;
}

.tiptap ul[data-type='taskList'] ul[data-type='taskList'] {
	margin: 0;
}

ul[data-type='taskList'] li[data-checked='true'] div {
	color: var(--task-completed-color);
	text-decoration: line-through;
}

.edra-editor input[type='checkbox'] {
	position: relative;
	top: 0rem;
	display: grid;
	place-content: center;
	width: 1.25rem;
	height: 1.25rem;
	margin: 0;
	-webkit-appearance: none;
	appearance: none;
	cursor: pointer;
	background-color: transparent;
	border: 1px solid var(--border-color);
	border-radius: 0.25rem;
}

.edra-editor input[type='checkbox']:hover {
	background-color: color-mix(in srgb, var(--muted) 50%, transparent);
}

.edra-editor input[type='checkbox']:active {
	background-color: var(--muted);
}

.edra-editor input[type='checkbox']::before {
	width: 0.75rem;
	height: 0.75rem;
	padding: 0.25rem;
	color: var(--secondary);
	content: '';
	box-shadow: inset 1em 1em;
	clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
	transform: scale(0);
	transform-origin: center;
	transition: 200ms transform ease-in-out;
}

.edra-editor input[type='checkbox']:checked {
	background-color: var(--secondary-foreground);
}

.edra-editor input[type='checkbox']:checked::before {
	transform: scale(1);
}

/* Color Swatches */
.color {
	white-space: nowrap;
}

.color::before {
	display: inline-block;
	width: 1rem;
	height: 1rem;
	margin-right: 0.1rem;
	margin-bottom: 0.15rem;
	vertical-align: middle;
	content: ' ';
	background-color: var(--color);
	border: 1px solid var(--border-color);
	border-radius: 0.25rem;
}

/* Code Block Styling */
.tiptap pre {
	display: flex;
	height: fit-content;
	padding: 0;
	margin: 0;
	overflow: auto;
	background-color: transparent;
}

.tiptap pre code {
	flex: 1;
	padding: 0;
	color: inherit;
	background-color: transparent;
	border-radius: 0 !important;
}

/* Math Equations (KaTeX) */
.katex:hover {
	background-color: var(--code-bg);
}

.katex.result {
	background-color: var(--highlight-color);
	border-bottom: 1px dashed var(--highlight-border);
}

/* Table Styling */
.tiptap,
.ProseMirror {
	/* New CSS variables for easy theming */
	--table-border-size: 1px;
	--table-selected-border-size: 2px;
	--table-resize-handle-thickness: 2px;
	--table-hover-transition: 200ms ease-in-out;
	--table-focus-ring: 2px;
}
.ProseMirror .tableWrapper {
	padding: 1.25rem 1rem;
	margin: 0;
	margin: 0.5rem 0;
	overflow-x: auto;
}

.ProseMirror table {
	box-sizing: border-box;
	width: 100%;
	margin-top: 1rem;
	margin-bottom: 1rem;
	border-collapse: collapse;
	border: var(--table-border-size) solid var(--table-border);
	border-radius: 0.25rem;
}

.ProseMirror table td,
.ProseMirror table th {
	position: relative;
	min-width: 100px;
	padding: 0.5rem;
	vertical-align: top;
	text-align: left;
	border: var(--table-border-size) solid var(--table-border);
}

.ProseMirror table td:first-of-type:not(a),
.ProseMirror table th:first-of-type:not(a) {
	margin-top: 0;
}

.ProseMirror table td p,
.ProseMirror table th p {
	margin: 0;
}

.ProseMirror table td p + p,
.ProseMirror table th p + p {
	margin-top: 0.75rem;
}

.ProseMirror table th {
	font-weight: bold;
	background-color: var(--table-bg-selected);
}

.ProseMirror table .column-resize-handle {
	position: absolute;
	top: 0;
	right: -2px;
	bottom: -2px;
	width: 2px;
	cursor: col-resize;
	background-color: var(--primary);
}

.ProseMirror table .selectedCell {
	/* Stronger visual, avoids collapse issues */
	z-index: 1;
	/* Stronger visual, avoids collapse issues */
	outline: 1px solid var(--primary);
	background-color: var(--table-bg-selected);
}

.ProseMirror .tableWrapper .grip-column,
.ProseMirror .tableWrapper .grip-row {
	position: absolute;
	z-index: 10;
	display: flex;
	align-items: center;
	justify-content: center;
	pointer-events: none;
	cursor: pointer;
	background-color: var(--table-bg-selected);
	opacity: 0;
	transition: opacity 150ms ease-in-out;
}

.ProseMirror table .grip-column {
	top: -0.9rem;
	left: 0;
	width: 100%;
	height: 0.8rem;
	margin-left: -1px;
	border: 0.25px solid var(--table-border);
	border-radius: 1rem;
}

.ProseMirror table .grip-column::before,
.ProseMirror table .grip-column.selected::before {
	width: 0.625rem;
	content: '';
}

.ProseMirror table .grip-column:hover {
	background-color: var(--table-bg-hover);
}

.ProseMirror table .grip-column::before {
	border-bottom: 2px dotted var(--border-color-hover);
}

.ProseMirror table .grip-column.selected {
	background-color: var(--table-bg-hover);
	border-color: var(--table-border);
	box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.ProseMirror table .grip-row {
	top: 0;
	left: -0.9rem;
	width: 0.8rem;
	height: calc(100%);
	margin-top: -1px;
	border: 0.5px solid var(--table-border);
	border-radius: 1rem;
}

.ProseMirror table .grip-row::before {
	height: 0.625rem;
	content: '';
	border-left: 2px dotted var(--border-color-hover);
}

.ProseMirror table .grip-row:hover {
	background-color: var(--table-bg-hover);
}

.ProseMirror table .grip-row.selected {
	background-color: var(--table-bg-hover);
	border-color: var(--table-border);
	box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

/* Cell grip — appears on cell hover or when selected */
/* .ProseMirror table .grip-cell {
	position: absolute;
	right: -0.125rem;
	translate: 0 calc(50% - 0.25rem);
	width: 0.5rem;
	height: 1rem;
	border-radius: 2px;
	background-color: var(--color-primary);
	opacity: 0;
	transition: all 200ms ease-in-out;
} */

.ProseMirror table td:hover .grip-cell,
.ProseMirror table th:hover .grip-cell,
.ProseMirror table .grip-cell.selected {
	opacity: 1;
}

/* Dynamic visibility classes for row/column grips */
.ProseMirror .tableWrapper .grip-row.show-row-grip,
.ProseMirror .tableWrapper .grip-column.show-col-grip {
	pointer-events: auto;
	opacity: 1;
}

/* Edge add buttons (Notion-like) */
.ProseMirror .add-column-btn,
.ProseMirror .add-row-btn {
	position: absolute;
	z-index: 20;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	color: var(--foreground);
	cursor: pointer;
	background-color: var(--muted);
	border: var(--table-border-size) solid var(--table-border);
	border-radius: 0.5rem;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
	opacity: 0;
	transform: scale(0.95);
	transition:
		opacity var(--table-hover-transition),
		transform var(--table-hover-transition),
		background-color var(--table-hover-transition);
}

/* Only show add buttons when flagged by wrapper classes */
.ProseMirror .tableWrapper.last-column-hover .add-column-btn,
.ProseMirror .tableWrapper.last-row-hover .add-row-btn {
	opacity: 1;
	transform: scale(1);
}

.ProseMirror .add-column-btn:hover,
.ProseMirror .add-row-btn:hover {
	background-color: var(--table-bg-hover);
	opacity: 0.95;
}

/* Positioning: column button flush right, full height. Row button flush bottom, full width */
.ProseMirror .add-column-btn {
	top: 0;
	right: -0.85rem;
	width: 0.75rem;
	height: 100%;
}

.ProseMirror .add-row-btn {
	bottom: -0.9rem;
	left: 0;
	width: 100%;
	height: 0.75rem;
}

/* Improve button hit areas via padding for better accessibility */
.ProseMirror .add-column-btn {
	padding: 0.25rem 0.125rem;
}
.ProseMirror .add-row-btn {
	padding: 0.125rem 0.25rem;
}

/* Focus states for accessibility */
.ProseMirror .add-column-btn:focus-visible,
.ProseMirror .add-row-btn:focus-visible {
	outline: var(--table-focus-ring) solid var(--primary);
	outline-offset: 2px;
}

.tiptap .search-result {
	color: black;
	background-color: var(--search-result-bg);
}

.tiptap .search-result-current {
	color: black;
	background-color: var(--search-result-current-bg);
}

.code-wrapper {
	position: relative;
	width: 100%;
	height: fit-content;
	padding: 1.5rem;
	margin: 1rem 0 !important;
	background-color: var(--codeblock-bg);
	border-radius: 0.5rem;
}

.code-wrapper-tile {
	position: absolute;
	top: 2px;
	right: 0;
	display: flex;
	gap: 1rem;
	align-items: center;
	justify-content: end;
	width: 100%;
	padding: 0 0.25rem;
	opacity: 0;
	transition: opacity 300ms ease-in-out;
}

.code-wrapper:hover .code-wrapper-tile {
	opacity: 1;
}

.tiptap iframe {
	aspect-ratio: 16 / 9;
}

/* Mathematics extension styles */
.tiptap .tiptap-mathematics-render {
	padding: 0 0.25rem;
	border-radius: 0.25rem;
}

/* Editable math block */
.tiptap .tiptap-mathematics-render--editable {
	cursor: pointer;
	transition: background 0.2s;
}

.tiptap .tiptap-mathematics-render--editable:hover {
	background: var(--code-bg);
}

/* Inline math */
.tiptap .tiptap-mathematics-render[data-type='inline-math'] {
	display: inline-block;
}

/* Block math */
.tiptap .tiptap-mathematics-render[data-type='block-math'] {
	display: block;
	padding: 0.5rem;
	margin: 1rem 0;
	font-size: 1.25rem;
	text-align: center;
}

/* Error styles */
.tiptap .tiptap-mathematics-render.inline-math-error,
.tiptap .tiptap-mathematics-render.block-math-error {
	color: var(--destructive);
	background: var(--code-bg);
	border: 1px solid darkred;
}

/* Drag Handle Styling */
.drag-handle {
	position: fixed;
	z-index: 50;
	width: 1.5rem;
	height: 1.5rem;
	display: flex;
	padding-right: 0.5rem;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	cursor: grab;
	opacity: 100;
	transition-property: all;
	transition-duration: 300ms;
	transition-timing-function: cubic-bezier(0.4, 0, 1, 1);
	color: var(--border-color-hover);
}

.drag-handle:active {
	cursor: grabbing;
}

.drag-handle.hide {
	opacity: 0;
	pointer-events: none;
}

@media screen and (max-width: 600px) {
	.drag-handle {
		display: none;
		pointer-events: none;
	}
}

.drag-handle svg {
	height: 1rem;
	width: 1rem;
}

/* One Dark and Light Theme for Highlight.js using Pure CSS */
/* Light Theme (Default) */
.tiptap pre code {
	color: #383a42;
}

/* Comment */
.hljs-comment,
.hljs-quote {
	font-style: italic;
	color: #a0a1a7;
}

/* Red */
.hljs-variable,
.hljs-template-variable,
.hljs-tag,
.hljs-name,
.hljs-selector-id,
.hljs-selector-class,
.hljs-regexp,
.hljs-deletion {
	color: #e45649;
}

/* Orange */
.hljs-number,
.hljs-built_in,
.hljs-literal,
.hljs-type,
.hljs-params,
.hljs-meta,
.hljs-link {
	color: #986801;
}

/* Yellow */
.hljs-attribute {
	color: #c18401;
}

/* Green */
.hljs-string,
.hljs-symbol,
.hljs-bullet,
.hljs-addition {
	color: #50a14f;
}

/* Blue */
.hljs-title,
.hljs-section {
	color: #4078f2;
}

/* Purple */
.hljs-keyword,
.hljs-selector-tag {
	color: #a626a4;
}

/* Cyan */
.hljs-emphasis {
	font-style: italic;
	color: #0184bc;
}

.hljs-strong {
	font-weight: bold;
}

/* Base styles */
.hljs-doctag,
.hljs-formula {
	color: #a626a4;
}

.hljs-attr,
.hljs-subst {
	color: #383a42;
}

/* Line highlights */
.hljs-addition {
	background-color: #e6ffed;
}

.hljs-deletion {
	background-color: #ffeef0;
}

/* Dark Theme (All dark styles consolidated in one media query) */
html.dark {
	.tiptap pre code {
		color: #abb2bf;
	}

	/* Comment */
	.hljs-comment,
	.hljs-quote {
		color: #5c6370;
	}

	/* Red */
	.hljs-variable,
	.hljs-template-variable,
	.hljs-tag,
	.hljs-name,
	.hljs-selector-id,
	.hljs-selector-class,
	.hljs-regexp,
	.hljs-deletion {
		color: #e06c75;
	}

	/* Orange */
	.hljs-number,
	.hljs-built_in,
	.hljs-literal,
	.hljs-type,
	.hljs-params,
	.hljs-meta,
	.hljs-link {
		color: #d19a66;
	}

	/* Yellow */
	.hljs-attribute {
		color: #e5c07b;
	}

	/* Green */
	.hljs-string,
	.hljs-symbol,
	.hljs-bullet,
	.hljs-addition {
		color: #98c379;
	}

	/* Blue */
	.hljs-title,
	.hljs-section {
		color: #61afef;
	}

	/* Purple */
	.hljs-keyword,
	.hljs-selector-tag {
		color: #c678dd;
	}

	/* Cyan */
	.hljs-emphasis {
		color: #56b6c2;
	}

	/* Base styles */
	.hljs-doctag,
	.hljs-formula {
		color: #c678dd;
	}

	.hljs-attr,
	.hljs-subst {
		color: #abb2bf;
	}

	/* Line highlights */
	.hljs-addition {
		background-color: #283428;
	}

	.hljs-deletion {
		background-color: #342828;
	}
}

import type { Editor, NodeViewProps } from '@tiptap/core';
import { flushSync, mount, unmount } from 'svelte';

interface RendererOptions<P extends Record<string, unknown>> {
	editor: Editor;
	props: P;
}

type App = ReturnType<typeof mount>;

// eslint-disable-next-line @typescript-eslint/no-explicit-any
class SvelteRenderer<R = unknown, P extends Record<string, any> = object> {
	id: string;
	component: App;
	editor: Editor;
	props: P;
	element: HTMLElement;
	ref: R | null = null;
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	mnt: Record<any, any> | null = null;

	constructor(component: App, { props, editor }: RendererOptions<P>) {
		this.id = Math.floor(Math.random() * 0xffffffff).toString();
		this.component = component;
		this.props = props;
		this.editor = editor;

		this.element = document.createElement('div');
		this.element.classList.add('svelte-renderer');

		if (this.editor.isInitialized) {
			// On first render, we need to flush the render synchronously
			// Renders afterwards can be async, but this fixes a cursor positioning issue
			flushSync(() => {
				this.render();
			});
		} else {
			this.render();
		}
	}

	render(): void {
		// eslint-disable-next-line @typescript-eslint/no-explicit-any
		this.mnt = mount(this.component as any, {
			target: this.element,
			props: {
				props: this.props
			}
		});
	}

	updateProps(props: Partial<NodeViewProps>): void {
		Object.assign(this.props, props);
		this.destroy();
		this.render();
	}

	updateAttributes(attributes: Record<string, string>): void {
		Object.keys(attributes).forEach((key) => {
			this.element.setAttribute(key, attributes[key]);
		});
		this.destroy();
		this.render();
	}

	destroy(): void {
		if (this.mnt) {
			unmount(this.mnt);
		} else {
			unmount(this.component);
		}
	}
}

export default SvelteRenderer;

