import { Node, nodeInputRule } from '@tiptap/core';
import { Plugin, PluginKey } from '@tiptap/pm/state';
import { toast } from 'svelte-sonner';
import strings from '../../strings.js';

export interface VideoOptions {
	HTMLAttributes: Record<string, unknown>;
}

declare module '@tiptap/core' {
	interface Commands<ReturnType> {
		video: {
			/**
			 * Set a video node
			 */
			setVideo: (src: string) => ReturnType;
			/**
			 * Toggle a video
			 */
			toggleVideo: (src: string) => ReturnType;
			/**
			 * Remove a video
			 */
			removeVideo: () => ReturnType;
		};
	}
}

const VIDEO_INPUT_REGEX = /!\[(.+|:?)]\((\S+)(?:(?:\s+)["'](\S+)["'])?\)/;

export const Video = (onDrop?: (file: File) => Promise<string>) =>
	Node.create<VideoOptions>({
		name: 'video',
		group: 'block',
		content: 'inline*',
		draggable: true,
		isolating: true,
		addOptions() {
			return {
				HTMLAttributes: {}
			};
		},
		addAttributes() {
			return {
				src: {
					default: null,
					parseHTML: (el) => (el as HTMLSpanElement).getAttribute('src'),
					renderHTML: (attrs) => ({ src: attrs.src })
				}
			};
		},
		parseHTML() {
			return [
				{
					tag: 'video',
					getAttrs: (el) => ({ src: (el as HTMLVideoElement).getAttribute('src') })
				}
			];
		},

		renderHTML({ HTMLAttributes }) {
			return [
				'video',
				{ controls: 'true', style: 'width: fit-content;', ...HTMLAttributes },
				['source', HTMLAttributes]
			];
		},
		addCommands() {
			return {
				setVideo:
					(src: string) =>
					({ commands }) =>
						commands.insertContent(
							`<video playsinline="true" preload="none" controls="true" src="${src}" style="display: block; width: fit-content"  />`
						),

				toggleVideo:
					() =>
					({ commands }) =>
						commands.toggleNode(this.name, 'paragraph'),
				removeVideo:
					() =>
					({ commands }) =>
						commands.deleteNode(this.name)
			};
		},
		addInputRules() {
			return [
				nodeInputRule({
					find: VIDEO_INPUT_REGEX,
					type: this.type,
					getAttributes: (match) => {
						const [, , src] = match;

						return { src };
					}
				})
			];
		},
		addProseMirrorPlugins() {
			return [
				new Plugin({
					key: new PluginKey('videoDropPlugin'),

					props: {
						handleDOMEvents: {
							paste(view, event) {
								const {
									state: { schema, tr },
									dispatch
								} = view;
								const hasFiles =
									event.clipboardData &&
									event.clipboardData.files &&
									event.clipboardData.files.length;

								if (!hasFiles) return false;

								const videos = Array.from(event.clipboardData.files).filter((file) =>
									/video/i.test(file.type)
								);

								if (videos.length === 0) return false;

								event.preventDefault();

								if (videos.length > 1) {
									toast.warning(strings.extension.video.multiplePasteWarningTitle, {
										description: strings.extension.video.multiplePasteWarningDescription
									});
								}

								const video = videos[0];
								const id = toast.loading(strings.extension.video.pasteProcessing);
								onDrop?.(video)
									.then((src) => {
										const node = schema.nodes.video.create({ src });
										const transaction = tr.replaceSelectionWith(node);
										dispatch(transaction);
										toast.dismiss(id);
									})
									.catch((err) => {
										console.error(err);
										toast.error(strings.extension.video.pasteError, { id });
									});

								return true;
							},
							drop(view, event) {
								const {
									state: { schema, tr },
									dispatch
								} = view;
								const hasFiles =
									event.dataTransfer && event.dataTransfer.files && event.dataTransfer.files.length;

								if (!hasFiles) return false;

								const videos = Array.from(event.dataTransfer.files).filter((file) =>
									/video/i.test(file.type)
								);

								if (videos.length === 0) return false;

								event.preventDefault();

								const coordinates = view.posAtCoords({ left: event.clientX, top: event.clientY });

								if (videos.length > 1) {
									toast.warning(strings.extension.video.multipleDropWarningTitle, {
										description: strings.extension.video.multipleDropWarningDescription
									});
								}

								const video = videos[0];
								const id = toast.loading(strings.extension.video.dropProcessing);
								onDrop?.(video)
									.then((src) => {
										if (coordinates && typeof coordinates.pos === 'number') {
											const node = schema.nodes.video.create({ src });
											const transaction = tr.insert(coordinates.pos, node);
											dispatch(transaction);
										}
										toast.dismiss(id);
									})
									.catch((err) => {
										console.error(err);
										toast.error(strings.extension.video.dropError, { id });
									});

								return true;
							}
						}
					}
				})
			];
		}
	});

import {
	type CommandProps,
	type Editor,
	mergeAttributes,
	Node,
	type NodeViewProps
} from '@tiptap/core';
import type { Component } from 'svelte';
import { SvelteNodeViewRenderer } from 'svelte-tiptap';

export interface VideoPlaceholderOptions {
	HTMLAttributes: Record<string, object>;
	onDrop: (files: File[], editor: Editor) => void;
	onDropRejected?: (files: File[], editor: Editor) => void;
	onEmbed: (url: string, editor: Editor) => void;
	allowedMimeTypes?: Record<string, string[]>;
	maxFiles?: number;
	maxSize?: number;
}

declare module '@tiptap/core' {
	interface Commands<ReturnType> {
		videoPlaceholder: {
			/**
			 * Inserts a video placeholder
			 */
			insertVideoPlaceholder: () => ReturnType;
		};
	}
}

export const VideoPlaceholder = (content: Component<NodeViewProps>) =>
	Node.create<VideoPlaceholderOptions>({
		name: 'video-placeholder',
		addOptions() {
			return {
				HTMLAttributes: {},
				onDrop: () => {},
				onDropRejected: () => {},
				onEmbed: () => {}
			};
		},
		parseHTML() {
			return [{ tag: `div[data-type="${this.name}"]` }];
		},

		renderHTML({ HTMLAttributes }) {
			return ['div', mergeAttributes(HTMLAttributes)];
		},
		group: 'block',
		draggable: true,
		atom: true,
		content: 'inline*',
		isolating: true,

		addNodeView() {
			return SvelteNodeViewRenderer(content);
		},
		addCommands() {
			return {
				insertVideoPlaceholder: () => (props: CommandProps) => {
					return props.commands.insertContent({
						type: 'video-placeholder'
					});
				}
			};
		}
	});

